Here's your expense tracker. Add an item, pick a category and set a monthly budget to see what's left. Entries last only while this page is open, so don't close it before you note down the totals.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#222}
  h2{margin:0 0 12px}
  .card{background:#fff;border-radius:12px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{padding:8px;border:1px solid #ccc;border-radius:8px;font-size:14px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
  button.x{background:#c0392b;padding:4px 8px}
  .big{font-size:22px;font-weight:600}
  .bar{height:8px;background:#e5e8e3;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .over{color:#c0392b}
  small{color:#666}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="budget" type="number" placeholder="Monthly budget (₹)" oninput="draw()">
  </div>
  <div class="big" id="spent">₹0</div>
  <small id="left">Set a budget to see what is left</small>
</div>

<div class="card">
  <div class="row">
    <input id="name" placeholder="What did you buy?">
    <input id="amt" type="number" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Travel</option><option>Bills</option>
      <option>Rent</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input id="day" type="date">
    <button onclick="add()">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>All entries</b><div id="list"></div></div>

<script>
var items = [];
var fmt = function(n){ return '₹' + Math.round(n).toLocaleString('en-IN'); };
document.getElementById('day').value = new Date().toISOString().slice(0,10);

function add(){
  var name = document.getElementById('name').value.trim();
  var amt = parseFloat(document.getElementById('amt').value);
  if(!name || !(amt > 0)) return;
  items.push({
    name: name, amt: amt,
    cat: document.getElementById('cat').value,
    day: document.getElementById('day').value
  });
  document.getElementById('name').value = '';
  document.getElementById('amt').value = '';
  draw();
}
function del(i){ items.splice(i,1); draw(); }

function draw(){
  var total = items.reduce(function(s,x){ return s + x.amt; }, 0);
  document.getElementById('spent').textContent = fmt(total) + ' spent';
  var b = parseFloat(document.getElementById('budget').value);
  var left = document.getElementById('left');
  if(b > 0){
    var r = b - total;
    left.textContent = r >= 0 ? fmt(r) + ' left of ' + fmt(b) : fmt(-r) + ' over your budget of ' + fmt(b);
    left.className = r >= 0 ? '' : 'over';
  } else {
    left.textContent = 'Set a budget to see what is left';
    left.className = '';
  }

  var by = {};
  items.forEach(function(x){ by[x.cat] = (by[x.cat] || 0) + x.amt; });
  var html = '';
  Object.keys(by).sort(function(a,c){ return by[c] - by[a]; }).forEach(function(k){
    var p = total ? by[k] / total * 100 : 0;
    html += '<div style="display:flex;justify-content:space-between"><span>' + k +
      '</span><span>' + fmt(by[k]) + '</span></div><div class="bar"><div style="width:' + p + '%"></div></div>';
  });
  document.getElementById('cats').innerHTML = html || '<small>Nothing yet</small>';

  var l = '';
  items.map(function(x,i){ return {x:x,i:i}; })
    .sort(function(a,c){ return c.x.day.localeCompare(a.x.day); })
    .forEach(function(o){
      l += '<div class="item"><span>' + o.x.name.replace(/</g,'&lt;') + '<br><small>' + o.x.cat +
        ' · ' + o.x.day + '</small></span><span>' + fmt(o.x.amt) +
        ' <button class="x" onclick="del(' + o.i + ')">✕</button></span></div>';
    });
  document.getElementById('list').innerHTML = l || '<small>No entries yet</small>';
}
draw();
</script>
</body>
</html>
```
